use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let mut recorded: u32 = 0;

        // Only a digest that was actually published marks its considered items as
        // seen; an unpublished digest leaves them to be considered again next run.
        if published.published {
            for id in published.considered.iter() {
                // Count only keys not already present, so duplicates in the input
                // and items seen in earlier runs are not counted again.
                if state_rw::get(id).is_none() {
                    state_rw::put(id, &published.date);
                    recorded = recorded.saturating_add(1);
                }
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
